def check_and_find_message(t):
    n = len(t)
    # Iterate over possible lengths of the original message s
    for length in range(1, n):
        s = t[:length]
        # Check if s can be repeated to form t with possible error
        for i in range(length, n, length):
            if i + length <= n and t[i:i + length] == s:
                continue
            elif i + length <= n:
                # Try to merge the last part with the start of the next part
                merge_len = 0
                for j in range(1, length):
                    if s[-j:] == t[i:i + j]:
                        merge_len = j
                        break
                # If a valid merge is found
                if merge_len > 0:
                    s += t[i + merge_len:]
                    break
            else:
                break
        else:
            # If no error is detected
            return "NO"
        # If we find a valid s
        return "YES\n" + s
    return "NO"

